def check(name, condition):
    RESULTS.append((name, bool(condition)))
    if not condition:
        raise AssertionError(name)

def close(name, a, b, tol=2e-10):
    check(name, np.linalg.norm(a-b) <= tol * max(1., np.linalg.norm(a), np.linalg.norm(b)))

def chains():
    # Independent direct inverses, including unequal endpoint slopes.
    for n in (1, 2, 4, 7):
        J=np.array([2.+i/13 for i in range(n)])
        q=np.array([.3+i/29 for i in range(n-1)])
        weights=np.empty(2*n-1);weights[::2]=J;weights[1::2]=q
        H=np.diag(weights,1)+np.diag(weights,-1); I=np.eye(2*n)
        R0=np.linalg.inv(-H)
        expected=(-1)**(n-1)*np.prod(q)/np.prod(J)
        close(f'chain{n}: endpoint cofactor', -R0[0,-1],expected)
        close(f'chain{n}: bandcenter diagonal',np.diag(R0),np.zeros(2*n))
        # Endpoint derivatives of (zI-H)^-1 are -H^-2, not +H^-2.
        step=1e-5; deriv=(np.linalg.inv(step*I-H)-np.linalg.inv(-step*I-H))/(2*step)
        close(f'chain{n}: slopes',deriv,-R0@R0)
        left=sum((np.prod(q[:k])/np.prod(J[:k+1]))**2 for k in range(n))
        right=sum((np.prod(q[n-1-k:])/np.prod(J[n-1-k:]))**2 for k in range(n))
        close(f'chain{n}: left slope',-deriv[0,0],left)
        close(f'chain{n}: right slope',-deriv[-1,-1],right)
        singular=np.linalg.eigvalsh(H)[n:]
        z=.11+.07j;R=np.linalg.inv(z*I-H)
        close(f'chain{n}: determinant ratio',R[0,-1]/R0[0,-1],np.prod(1/(1-z*z/singular**2)))
        check(f'chain{n}: positive gap',singular[0]>=min(J)-max(q,default=0)-1e-12)
    check('nonuniform unequal endpoint slopes',abs(left-right)>1e-5)

def ordered_forcing():
    rng=np.random.default_rng(20261018)
    def herm(n,shift):
        x=rng.normal(size=(n,n))+1j*rng.normal(size=(n,n));return (x+x.conj().T)/10+(shift+.4j)*np.eye(n)
    A,D,T=herm(3,4),herm(4,5),herm(2,3)
    B=(rng.normal(size=(3,4))+1j*rng.normal(size=(3,4)))/5
    E=(rng.normal(size=(4,2))+1j*rng.normal(size=(4,2)))/5
    full=np.block([[A,B,np.zeros((3,2))],[B.conj().T,D,E],[np.zeros((2,3)),E.conj().T,T]])
    G=np.linalg.inv(T);L=np.linalg.inv(D-E@G@E.conj().T);S=np.linalg.inv(A-B@L@B.conj().T)
    left=np.vstack((np.eye(3),-L@B.conj().T));right=np.hstack((np.eye(3),-B@L))
    direct=np.zeros((7,7),complex);direct[3:,3:]=L
    K=left@S@right+direct;inv=np.linalg.inv(full)
    close('full arbitrary forcing Schur inverse',K,inv[:7,:7])
    port=E.conj().T@L@B.conj().T@S@right-E.conj().T@L@np.hstack((np.zeros((4,3)),np.eye(4)))
    close('full port row including interior forcing',G@port,inv[7:,:7])
    wrong=G@E.conj().T@L@B.conj().T@S@right
    check('dropped interior forcing mutant rejected',np.linalg.norm(wrong-inv[7:,:7])>.01)
    check('lip adjoint mutant rejected',np.linalg.norm(L-L.conj().T)>.01)
    error=np.diag(np.linspace(-.003,.005,7));pert=np.linalg.inv(np.linalg.inv(K)-error)
    close('ordered Dyson identity',pert-K,K@error@pert)
    # One-head onsite norm has no number-of-heads multiplier.
    check('onsite diagonal norm',np.linalg.norm(error,2)==.005)

def physical_blocks():
    X=np.array([[0,1],[1,0]],complex);Y=np.array([[0,-1j],[1j,0]]);number=np.diag([0,1])
    hopping=(np.kron(X,X)+np.kron(Y,Y))/2
    occupation=np.kron(number,np.eye(2))+np.kron(np.eye(2),number)
    weight=.17;P=weight*(np.eye(4)-hopping);Q=weight*(occupation-hopping)
    close('positive P block spectrum',np.linalg.eigvalsh(P),np.array([0,weight,weight,2*weight]))
    close('compensated Q to P full-space identity',Q+weight*(np.eye(4)-occupation),P)
    gamma,J,q=.013,2.,.3
    bonds=np.array([gamma,J,q,J]);H=np.diag(bonds,1)+np.diag(bonds,-1)
    seed=np.eye(5)[:,0]
    close('actual product seed second moment',np.vdot(seed,H@H@seed),gamma**2)
    check('effective weak hopping is not seed moment',abs(gamma**2-(gamma**2*q/J**2)**2)>1e-5)
    n=4;r=q/J;d=(1-r**(2*n))/(J**2-q**2)
    edges=np.empty(2*n-1);edges[::2]=J;edges[1::2]=q
    chain=np.diag(edges,1)+np.diag(edges,-1)
    close('uniform endpoint mass derivative',np.linalg.matrix_power(np.linalg.inv(chain),2)[0,0],d)

